/*! Minimal QR helper stub + optional qrencode-free text fallback.
 * Full matrix QR on the host is served at /qr.svg (qrencode when available).
 * window.CompanionQR.draw(el, text) renders a monospaced URL card.
 */
(function (g) {
  function draw(el, text) {
    if (!el) return;
    el.innerHTML = "";
    var pre = document.createElement("pre");
    pre.style.cssText = "margin:0;padding:12px;background:#1a1a26;border-radius:12px;color:#4fd1c5;font:11px/1.35 ui-monospace,monospace;white-space:pre-wrap;word-break:break-all;";
    pre.textContent = String(text || "");
    el.appendChild(pre);
  }
  g.CompanionQR = { draw: draw };
})(typeof window !== "undefined" ? window : this);
